# -*- coding: utf-8 -*-
L, A, R, M, J, N, B, H = "Léa", "Antoine", "Gérard", "Margaux", "Julien", "Nicole", "Bernard", "Hugo"
D = [
(None, "Mercredi 24 décembre, 17 h. La ferme des Delcourt, à Saint-Cyr-en-Bourg, baigne dans la lumière rose d'un crépuscule d'hiver. Dans la cour, un sapin décoré de guirlandes artisanales. Une fumée blanche monte de la cheminée. Une voiture grise s'arrête devant la grille : Léa, Antoine, Nicole, Bernard et Hugo en descendent, chargés de sacs et de paquets.", "12월 24일 수요일 오후 5시. 생시르앙부르의 델쿠르 농가가 겨울 해 질 녘의 장밋빛 속에 잠겨 있다. 마당에는 수제 전구 줄로 장식한 전나무. 굴뚝에서 흰 연기가 피어오른다. 회색 자동차가 대문 앞에 멈추고 레아, 앙투안, 니콜, 베르나르, 위고가 가방과 꾸러미를 가득 들고 내린다."),
(H, "(sort de la voiture en s'étirant) Quatre heures de route. Mes jambes sont en train de me quitter.", "(차에서 내려 기지개를 켜며) 네 시간 운전이야. 다리가 날 떠나려고 해."),
(N, "Tu n'as pas conduit, Hugo. Tu as dormi à l'arrière.", "위고, 넌 운전 안 했어. 뒷좌석에서 잤잖아."),
(H, "Dormir en voiture, c'est épuisant, maman. Il faut se tenir en équilibre pendant les virages.", "차에서 자는 것도 피곤해, 엄마. 커브마다 균형을 잡아야 하거든."),
(B, "(un homme sec, aux lunettes rondes, qui regarde la maison avec une gravité sceptique) Ce n'est pas mal, cette ferme. Les murs sont solides.", "(둥근 안경을 쓴 마른 남자가 회의적인 진지함으로 집을 바라보며) 이 농가 나쁘지 않네. 벽이 튼튼해."),
(L, "Papa, tu juges les murs avant même d'avoir salué.", "아빠, 인사도 하기 전에 벽부터 평가하시네요."),
(B, "Je suis ingénieur, Léa. Je regarde ce qui tient debout.", "난 엔지니어야, 레아. 서 있는 걸 보는 거지."),
(None, "La porte de la ferme s'ouvre. Gérard apparaît, en pull de laine épais, un tablier de cuisine noué autour de la taille. Il descend les marches du perron, s'arrête face à Bernard. Les deux hommes se regardent sans un mot.", "농가 문이 열린다. 두꺼운 털 스웨터에 부엌 앞치마를 두른 제라르가 나타난다. 그가 현관 계단을 내려와 베르나르 앞에 선다. 두 남자가 말없이 서로를 바라본다."),
(R, "Monsieur Fontaine.", "퐁텐 씨."),
(B, "Monsieur Delcourt.", "델쿠르 씨."),
(R, "Vous avez fait bon voyage ?", "여행은 좋으셨습니까?"),
(B, "Long. Mais sans accident.", "길었어요. 하지만 사고는 없었죠."),
(R, "Tant mieux. Entrez, je vous en prie. Il fait froid.", "다행이네요. 들어오세요. 춥습니다."),
(None, "Les deux hommes se serrent la main, brièvement, fermement. Nicole et Margaux, derrière eux, échangent un regard amusé.", "두 남자가 짧고 단단하게 악수한다. 뒤에서 니콜과 마르고가 재미있다는 듯 눈빛을 주고받는다."),
(M, "(à voix basse, à Nicole) Ils vont se parler en monosyllabes jusqu'au dessert.", "(니콜에게 작은 소리로) 디저트까지 단음절로만 말하겠네요."),
(N, "(à voix basse) Mon mari est capable de ne rien dire pendant trois heures. J'ai l'habitude.", "(작은 소리로) 우리 남편은 세 시간 동안 아무 말 안 할 수도 있어요. 익숙해요."),
(M, "Celui-ci est capable de ne rien dire pendant trois jours.", "이쪽은 사흘도 아무 말 안 할 수 있어요."),
(N, "Alors ce sera un Noël très paisible.", "그럼 아주 평화로운 크리스마스가 되겠네요."),
(None, "Dans la grande cuisine : un immense poêle en fonte, des casseroles qui frémissent, une table de ferme déjà dressée pour dix. L'odeur du chapon rôti, du beurre, du thym et du vin chaud emplit la pièce. Julien, en tablier lui aussi, émince des échalotes.", "큰 부엌에는 거대한 주철 난로, 끓는 냄비들, 열 명 몫으로 이미 차려진 농가 식탁이 있다. 구운 거세 닭, 버터, 타임, 뱅쇼 냄새가 방을 가득 채운다. 마찬가지로 앞치마를 두른 쥘리앵이 샬롯을 썰고 있다."),
(J, "Léa ! Joyeux Noël ! Je t'embrasse avec des mains qui sentent l'oignon.", "레아! 메리 크리스마스! 양파 냄새 나는 손으로 안아 줄게."),
(L, "Julien, c'est un parfum que j'apprécie.", "쥘리앵, 난 그 향 좋아해."),
(J, "Tu connais Margaux. Et voici Nicole et Bernard, tes parents. Enchanté, madame, monsieur. Je suis le mauvais garçon qui a proposé un partenariat à votre futur gendre.", "마르고는 알지. 그리고 니콜 씨와 베르나르 씨, 레아 부모님이시죠. 반갑습니다, 부인, 선생님. 장래 사위분에게 파트너십을 제안한 나쁜 놈이에요."),
(B, "(regard sévère, une seconde) Futur gendre ?", "(잠시 엄한 눈빛으로) 장래 사위?"),
(J, "(se rattrape) Euh... Un terme générique. Ce n'est pas officiel.", "(만회하려 하며) 어... 일반적인 표현이에요. 공식은 아니고요."),
(N, "(sourit) Officiel ou pas, Julien, c'est la direction que prennent les choses.", "(미소 지으며) 공식이든 아니든 쥘리앵, 일이 흘러가는 방향이 그래요."),
(B, "Nicole.", "니콜."),
(N, "Bernard. Pas de commentaire. C'est Noël.", "베르나르. 논평 금지. 크리스마스잖아요."),
(None, "Plus tard, autour de la grande table. Dix couverts, des bougies, du lierre et du houx. Au centre, un plateau d'huîtres de Bretagne. Gérard présente, avec une fierté pudique, une bouteille couchée dans un panier.", "잠시 뒤 큰 식탁 둘레에서. 열 개의 식기, 양초, 담쟁이와 호랑가시나무. 가운데에는 브르타뉴 굴 접시. 제라르가 수줍은 자부심으로 바구니에 눕힌 병 하나를 소개한다."),
(R, "Un Muscadet sur lie, de mille neuf cent quatre-vingt-dix-neuf. Je l'ai acheté la même année que la naissance de Margaux. Elle voulait qu'on le boive pour ses vingt-cinq ans. Elle en a trente et un.", "1999년산 뮈스카데 쉬르 리야. 마르고가 태어난 해에 샀어. 걔가 스물다섯 살 때 마시자고 했는데 지금은 서른한 살이지."),
(M, "Papa a la mémoire sélective. J'avais dit trente ans.", "아빠는 기억을 골라서 하세요. 난 서른 살이라고 했어요."),
(R, "Trente, vingt-cinq : le principe est le même.", "서른이든 스물다섯이든 원리는 같지."),
(None, "Il ouvre la bouteille. Le bouchon sort avec un « pop » discret. Il sert un petit fond de vin à chacun. Léa regarde le plateau d'huîtres avec une expression que seul Antoine reconnaît.", "그가 병을 연다. 코르크가 작은 '퐁' 소리를 낸다. 모두에게 소량씩 따른다. 레아가 굴 접시를 바라보는 표정을 앙투안만 알아본다."),
(A, "(à voix basse) Tu n'es pas obligée.", "(작은 소리로) 억지로 안 해도 돼."),
(L, "(à voix basse) Je sais. Mais c'est un jour pour les premières fois.", "(작은 소리로) 알아. 하지만 오늘은 처음을 시도하는 날이야."),
(R, "(l'observe discrètement) Mademoiselle Léa... Léa. Vous aimez les huîtres ?", "(조용히 그녀를 관찰하며) 레아 양... 레아. 굴 좋아하세요?"),
(L, "Je n'en ai jamais mangé, monsieur. Gérard. Mais j'ai eu quelqu'un, longtemps, qui me disait qu'elles étaient « moins terribles qu'elles n'en ont l'air ».", "먹어 본 적이 없어요, 선생님... 제라르 씨. 하지만 오랫동안 어떤 사람이 굴은 '보기만큼 무섭지 않다'고 말했어요."),
(R, "(un sourire discret) Mon fils dit cela depuis qu'il a dix ans.", "(은은한 미소) 우리 아들은 열 살 때부터 그 말을 했죠."),
(L, "Alors je vais vérifier.", "그럼 확인해 볼게요."),
(None, "Elle prend une huître, hésite, regarde Antoine, puis la porte à ses lèvres. Silence autour de la table. Elle avale. Tous la regardent.", "그녀가 굴 하나를 집고 망설이다 앙투안을 보더니 입에 가져간다. 식탁에 침묵이 흐른다. 그녀가 삼킨다. 모두가 그녀를 바라본다."),
(H, "(retenant son souffle) Alors ?", "(숨을 멈추고) 어때?"),
(L, "(un temps, étonnée) C'est... iodé. Frais. Un goût de mer et de citron. Ce n'est pas désagréable.", "(잠시 후 놀라며) 요오드 맛이야. 신선하고. 바다와 레몬 맛. 불쾌하지 않아."),
(A, "(fou de joie) Elle a mangé une huître !", "(기뻐 날뛰며) 굴을 먹었어!"),
(L, "Ne fais pas de scandale. Je n'en reprendrai pas douze.", "소란 피우지 마. 열두 개를 더 먹진 않을 거야."),
(R, "(lève son verre) Dans ma famille, on dit : « Celui qui mange sa première huître le soir de Noël entre dans la famille. »", "(잔을 들며) 우리 집안에서는 이렇게 말해요. '크리스마스 저녁에 첫 굴을 먹는 사람은 가족이 된다.'"),
(M, "(sceptique) Papa, c'est la première fois que j'entends ce dicton.", "(의심스럽게) 아빠, 그 속담은 처음 들어요."),
(R, "Je viens de l'inventer. Mais il est joli.", "방금 만들었어. 하지만 예쁘지."),
(None, "Rires autour de la table. Nicole prend la main de Bernard, qui sourit, sans doute pour la première fois de la soirée.", "식탁 주위에서 웃음이 터진다. 니콜이 베르나르의 손을 잡는다. 아마 이날 처음으로 그가 미소 짓는다."),
(B, "Monsieur Delcourt. Votre Muscadet est excellent.", "델쿠르 씨. 뮈스카데가 훌륭합니다."),
(R, "Merci. Votre fille a goûté mon fils, donc l'honneur est partagé.", "고맙습니다. 따님이 제 아들을 맛봤으니 명예는 나눠 갖는 거죠."),
(B, "(décontenancé, puis éclate d'un rire franc, inattendu) C'est la meilleure que j'aie entendue depuis des années.", "(당황하다가 뜻밖에 시원하게 웃음을 터뜨리며) 몇 년 만에 들은 최고의 농담이군요."),
(N, "(stupéfaite) Bernard, tu ris.", "(놀라서) 베르나르, 웃네요."),
(B, "Je ris, oui. Je ris de bon cœur. Ça m'arrive une fois tous les quinze ans.", "웃어요. 진심으로. 십오 년에 한 번 있는 일이죠."),
(H, "(à voix basse, à Léa) Papa rit. C'est l'apocalypse.", "(레아에게 작은 소리로) 아빠가 웃어. 종말이야."),
(L, "(à voix basse) C'est la paix.", "(작은 소리로) 평화야."),
(None, "Après l'apéritif, la dinde farcie aux marrons, le chapon rôti, le foie gras de canard sur du pain d'épices, les haricots verts, les pommes de terre sarladaises, une salade de mâche. Un Saumur-Champigny du domaine accompagne le plat principal. Le fromage, puis la bûche de Noël, au chocolat et à la crème de marron.", "식전주 뒤에는 밤으로 속을 채운 칠면조, 구운 거세 닭, 향신료 빵에 얹은 오리 푸아그라, 껍질콩, 사를라식 감자, 콘샐러드가 나온다. 주요리에는 농장의 소뮈르샹피니가 곁들여진다. 그다음은 치즈, 그리고 초콜릿과 밤 크림으로 만든 부슈 드 노엘."),
(N, "Gérard, ce chapon est merveilleux. Quelle est votre recette ?", "제라르 씨, 이 거세 닭 정말 훌륭하네요. 레시피가 뭐예요?"),
(R, "Du beurre, du thym, et un peu de patience. Le reste, c'est Julien.", "버터, 타임, 그리고 약간의 인내예요. 나머지는 쥘리앵이 해요."),
(J, "J'ai surtout surveillé le four. Gérard a tout fait avec les mains.", "저는 오븐만 지켜봤어요. 제라르 씨가 손으로 다 하셨죠."),
(B, "Vous cuisinez, Gérard ?", "제라르 씨가 요리하세요?"),
(R, "Depuis que ma femme n'est plus là. Il fallait bien que quelqu'un apprenne.", "아내가 없어진 뒤로요. 누군가는 배워야 했으니까요."),
(N, "(doucement) D'après Antoine, c'était une femme remarquable.", "(조용히) 앙투안 말로는 대단한 분이셨다고요."),
(R, "Elle chantait en cuisinant. Elle chantait faux, d'ailleurs. Mais personne n'a jamais osé le lui dire.", "요리하면서 노래했죠. 음정이 틀렸어요, 사실. 하지만 아무도 감히 말하지 못했어요."),
(H, "Alors c'est un trait de famille : chez nous aussi, tout le monde chante faux.", "그럼 집안 내력이네요. 저희 집도 다들 음정이 틀려요."),
(M, "Mais avec conviction.", "하지만 확신을 가지고."),
(L, "(à voix basse, à Antoine) Ta mère aurait aimé cette soirée.", "(앙투안에게 작은 소리로) 네 어머니가 이 저녁을 좋아하셨을 거야."),
(A, "(à voix basse) Elle est là. Je la sens dans la cuisine.", "(작은 소리로) 여기 계셔. 부엌에서 느껴져."),
(N, "Levons nos verres à ceux qui ne sont pas à table.", "식탁에 없는 이들을 위해 잔을 들어요."),
(R, "À Anne.", "안을 위해."),
(B, "À Anne, alors. Et à tous les absents.", "그럼 안을 위해. 그리고 모든 부재자를 위해."),
(H, "À Anne !", "안을 위해!"),
(M, "(la voix un peu étranglée) À maman.", "(목이 조금 메어) 엄마를 위해."),
(None, "Vers vingt-trois heures, la table est jonchée de miettes et de bouteilles vides. Hugo, assis sur un tabouret près du poêle, gratte doucement sa guitare. Les parents bavardent. Antoine et Léa échangent un regard. Antoine se lève et s'approche de son père.", "밤 11시경 식탁에는 부스러기와 빈 병이 흩어져 있다. 위고가 난로 곁 스툴에 앉아 조용히 기타를 퉁긴다. 부모님들은 수다를 떤다. 앙투안과 레아가 눈빛을 주고받는다. 앙투안이 일어나 아버지에게 다가간다."),
(A, "Papa, tu as une minute ? Dehors ?", "아빠, 잠깐 시간 있어요? 밖에서요."),
(R, "(le regarde, comprend) Allons voir si les étoiles sont toujours là.", "(그를 바라보다 알아차리고) 별이 아직 있는지 보러 가자."),
(None, "Ils sortent sur le perron. L'air est vif, très pur. Le ciel est criblé d'étoiles. Au loin, les vignes dorment sous un givre léger, comme une immense nappe d'argent.", "둘이 현관으로 나선다. 공기가 맵고 아주 맑다. 하늘은 별로 가득하다. 멀리 포도밭이 가벼운 서리를 덮고 잠들어 있다. 거대한 은빛 식탁보 같다."),
(R, "Alors. Tu as quelque chose à me dire.", "그래. 할 말이 있겠지."),
(A, "Oui. Papa, je ne te demande rien. Je veux d'abord que tu le saches.", "네. 아빠, 부탁하는 건 아니에요. 먼저 알아 두셨으면 해요."),
(R, "Je m'en doute. Tu me parles de la banque ?", "짐작은 해. 은행 얘기냐?"),
(A, "(un temps, surpris) Comment le sais-tu ?", "(잠시 놀라며) 어떻게 아세요?"),
(R, "Ta sœur me téléphone tous les soirs depuis un mois. Elle m'a tout dit. Elle m'a même fait lire ton dossier. Il est excellent.", "누나가 한 달째 매일 저녁 전화했어. 다 말해 줬지. 네 서류도 읽게 했다. 훌륭하더구나."),
(A, "(sourit) Margaux. Évidemment.", "(미소 지으며) 마르고. 당연하지."),
(R, "Elle m'a dit que la banque demandait une caution personnelle de soixante-cinq mille euros.", "은행이 6만 5천 유로의 개인 보증을 요구한다고 하더구나."),
(A, "Oui. Mais papa, je ne veux pas que tu...", "네. 하지만 아빠, 저는 아빠가..."),
(R, "Laisse-moi finir. J'ai réfléchi pendant tout le mois. J'ai pensé à ta mère, aux vignes, au domaine, à ce que je t'ai demandé toute ma vie. Je t'ai demandé de rester. Je me suis trompé.", "끝까지 말하게 해라. 한 달 내내 생각했다. 네 엄마, 포도밭, 농장, 평생 네게 요구한 것에 대해서. 난 네게 남아 달라고 했지. 내가 틀렸다."),
(A, "(très ému) Papa...", "(깊이 감동하여) 아빠..."),
(R, "Ce que je veux, maintenant, c'est que tu sois heureux. Pas près de moi. Heureux. Et si ta boutique de Montmartre te rend heureux, alors je me porterai caution.", "지금 내가 원하는 건 네가 행복한 거다. 내 곁이 아니라 행복한 거. 몽마르트르 가게가 널 행복하게 한다면 내가 보증을 서겠다."),
(A, "Papa, c'est soixante-cinq mille euros. Si on échoue...", "아빠, 6만 5천 유로예요. 실패하면..."),
(R, "Si vous échouez, on vendra un hectare. Je n'en ai pas besoin de quinze. Je n'ai besoin que de savoir que tu vis.", "실패하면 1헥타르를 팔면 돼. 열다섯 개는 필요 없다. 네가 산다는 걸 알기만 하면 돼."),
(A, "(la voix tremble) Je ne sais pas quoi dire.", "(목소리가 떨리며) 뭐라고 해야 할지 모르겠어요."),
(R, "Ne dis rien. Mais promets-moi deux choses.", "아무 말 마라. 하지만 두 가지만 약속해라."),
(A, "Tout ce que tu veux.", "뭐든지요."),
(R, "Un : que tu reviennes chaque année pour les vendanges. Deux : que tu emmènes cette jeune fille, qu'elle respire l'air du domaine au moins une fois par an. Je veux qu'elle sache d'où tu viens.", "하나, 해마다 수확철에 돌아올 것. 둘, 그 아가씨를 데려와서 일 년에 한 번은 농장 공기를 마시게 할 것. 네가 어디서 왔는지 알아야 하니까."),
(A, "C'est promis.", "약속해요."),
(None, "Un pas sur le perron. Bernard est là, les mains dans les poches, la silhouette un peu raide. Il a entendu les derniers mots.", "현관에서 발소리가 난다. 베르나르가 주머니에 손을 넣고 약간 굳은 실루엣으로 서 있다. 마지막 말을 들었다."),
(B, "Excusez-moi. Je ne voulais pas écouter. Je sortais pour prendre l'air.", "죄송합니다. 엿들으려던 건 아니에요. 바람 쐬러 나왔어요."),
(R, "Monsieur Fontaine. Restez. Nous parlions justement de vos enfants.", "퐁텐 씨. 계세요. 마침 자제분 얘기를 하고 있었습니다."),
(B, "(un long silence) Monsieur Delcourt. J'ai entendu parler de la caution. Je tiens à vous dire quelque chose. Léa est ma fille. Cette boutique est aussi son projet. Si votre fils échoue, ma fille échoue.", "(긴 침묵) 델쿠르 씨. 보증 얘기를 들었습니다. 한 말씀 드리고 싶습니다. 레아는 제 딸입니다. 이 가게는 그 애의 프로젝트이기도 해요. 아드님이 실패하면 제 딸도 실패하는 겁니다."),
(R, "C'est exact.", "맞습니다."),
(B, "Alors le risque n'est pas qu'à vous. Je voudrais en prendre ma part. Une part équitable. Si la caution est de soixante-cinq mille euros, je propose de couvrir vingt-cinq mille. Vous couvrirez quarante.", "그럼 위험이 당신 혼자의 몫이 아닙니다. 제 몫을 지고 싶어요. 공정한 몫으로요. 보증액이 6만 5천 유로라면 제가 2만 5천을 맡겠습니다. 당신이 4만을 맡으시고요."),
(R, "(un temps, très ému) Monsieur Fontaine... Bernard. Vous ne me devez rien.", "(잠시 후 매우 감동하여) 퐁텐 씨... 베르나르 씨. 제게 빚진 건 없어요."),
(B, "Je ne le fais pas pour vous. Je le fais pour ma fille. Mais aussi parce que... (il hésite, c'est rare chez lui) parce que ce soir, j'ai ri. Et ça faisait quinze ans.", "당신을 위해서가 아닙니다. 제 딸을 위해서죠. 하지만 또... (이례적으로 망설이며) 오늘 저녁 제가 웃었으니까요. 십오 년 만이었습니다."),
(A, "(la voix cassée) Monsieur Fontaine... Merci.", "(목소리가 갈라지며) 퐁텐 씨... 감사합니다."),
(B, "Appelez-moi Bernard. Et ne me remerciez pas : réussissez.", "베르나르라고 부르게. 그리고 고마워하지 말고 성공해."),
(R, "(tend la main) Bernard. Alors c'est convenu : quarante mille de ma part, vingt-cinq de la vôtre.", "(손을 내밀며) 베르나르 씨. 그럼 합의됐네요. 제 몫 4만, 당신 몫 2만 5천."),
(B, "(serre la main) Convenu, Gérard.", "(악수하며) 합의했습니다, 제라르 씨."),
(None, "Les deux hommes se serrent la main longuement, au milieu des étoiles et du froid, sous le regard silencieux d'Antoine. La porte de la ferme s'ouvre : Léa apparaît, un châle sur les épaules.", "두 남자가 별과 추위 속에서 오래 악수한다. 앙투안이 말없이 지켜본다. 농가 문이 열리고 어깨에 숄을 두른 레아가 나타난다."),
(L, "Qu'est-ce que vous faites tous les trois dehors, dans le froid ?", "세 분이서 추운 밖에서 뭘 하세요?"),
(A, "(sourit, ému) Je te raconterai. Plus tard.", "(감동하여 미소 지으며) 나중에 얘기해 줄게."),
(L, "(regarde les trois visages) Je crois que j'ai déjà compris.", "(세 사람의 얼굴을 보며) 이미 이해한 것 같아."),
(R, "Mademoiselle Léa, venez. Il est presque minuit. C'est l'heure où l'on ouvre le Champagne de la maison.", "레아 양, 이리 와요. 거의 자정이에요. 이 집 샴페인을 여는 시간이에요."),
(H, "(sa guitare à la main, sur le seuil) Je commence la chanson de minuit. Venez tous. Même papa Bernard.", "(기타를 손에 들고 문턱에서) 자정의 노래를 시작해요. 모두 와요. 베르나르 아버지도."),
(B, "Je ne chante pas.", "난 노래 안 해."),
(H, "Tu chantes faux, papa. Ça suffit.", "아빠는 음정이 틀리잖아요. 그걸로 충분해요."),
(None, "Ils rentrent tous les quatre dans la cuisine chaude. À l'intérieur, tout le monde se rassemble autour de la table. Les premières notes de guitare s'élèvent, doucement, dans la lumière des bougies.", "넷이 따뜻한 부엌으로 돌아간다. 안에서는 모두가 식탁 주위에 모인다. 촛불 속에서 기타의 첫 음이 부드럽게 퍼진다."),
]
